<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\User; use Illuminate\Http\Request;
class AdminUserController extends Controller { public function index(Request $request){$users=User::with(['studentProfile','lecturerProfile'])->when($request->role,fn($q,$v)=>$q->where('role',$v))->when($request->department,fn($q,$v)=>$q->where(fn($i)=>$i->whereHas('studentProfile',fn($p)=>$p->where('department',$v))->orWhereHas('lecturerProfile',fn($p)=>$p->where('department',$v))))->when($request->program,fn($q,$v)=>$q->whereHas('studentProfile',fn($p)=>$p->where('program_name',$v)))->when($request->filled('status'),fn($q)=>$q->where('is_active',$request->boolean('status')))->latest()->paginate(20)->withQueryString();return view('admin.users.index',compact('users'));} public function show(User $user){return view('admin.users.show',['user'=>$user->load(['studentProfile','lecturerProfile','resources'])]);} public function update(Request $request,User $user){$data=$request->validate(['name'=>['required','string','max:255'],'email'=>['required','email','max:255','unique:users,email,'.$user->id],'role'=>['required','in:student,lecturer,admin'],'is_active'=>['required','boolean']]);$user->update($data);return back()->with('status','User updated.');} public function destroy(Request $request,User $user){abort_if($user->id===$request->user()->id,422,'You cannot delete your own administrator account.');$user->delete();return redirect()->route('admin.users.index')->with('status','User deleted.');} }
